from __future__ import annotations

import json
from typing import Any

from system.cs.lib.ops import remove_subtree
from system.state.api import write_value

from ..contracts import LayoutInstance, dispatch_none, dispatch_self
from .. import state as layout_state

MODULE = "editor"
TITLE = "EDITOR"
STORAGE_PREFIX = "EDITOR"
PRIMARY_WRITE_FIELD = "content"
_VALUE_KEY = "__value__"

DEFAULT_CONFIG = {}

CONFIG_SCHEMA = {
    "title": "string?",
    "prompt": "string?",
    "instance_suffix": "string?",
    "target_symbol": "string?",
    "target_save_mode": "string?",
    "target_value_kind": "string?",
}

KEYBINDS = {}


def _read_text_content(ctx, handle: str) -> str:
    raw = layout_state.get_primary(ctx, handle)
    if isinstance(raw, str):
        return raw
    return layout_state.stringify_payload(raw)


def _load_editor_value(raw_text: str):
    text = str(raw_text or "")
    stripped = text.strip()
    if stripped == "":
        return ""

    if stripped[0] in "[{\"" or stripped in ("true", "false", "null"):
        return json.loads(stripped)

    try:
        if stripped[0] in "-0123456789":
            return json.loads(stripped)
    except Exception:
        pass

    return text


def _parse_by_value_kind(raw_text: str, value_kind: str):
    kind = str(value_kind or "").strip().lower()
    if kind in ("dict", "list", "int", "float", "bool", "nonetype", "none"):
        stripped = str(raw_text or "").strip()
        if stripped == "":
            if kind == "dict":
                return {}
            if kind == "list":
                return []
            if kind in ("bool",):
                raise ValueError("boolean value cannot be empty")
            if kind in ("int", "float"):
                raise ValueError(f"{kind} value cannot be empty")
            return None
        return json.loads(stripped)
    return str(raw_text or "")


def _clear_symbol_subtree(state, target_symbol: str) -> None:
    try:
        remove_subtree(state, target_symbol)
    except Exception:
        try:
            state.delete(target_symbol)
        except Exception:
            pass


def _write_branch_node(state, target_symbol: str, value: Any) -> None:
    if isinstance(value, dict):
        exact_present = _VALUE_KEY in value
        child_keys = [str(key) for key in value.keys() if str(key) != _VALUE_KEY]

        if exact_present:
            out = write_value(
                state,
                target_symbol,
                value.get(_VALUE_KEY),
                writer="editor",
                op="editor_save",
            )
            if out.get("error"):
                raise ValueError(out["error"])
        elif not child_keys:
            out = write_value(
                state,
                target_symbol,
                {},
                writer="editor",
                op="editor_save",
            )
            if out.get("error"):
                raise ValueError(out["error"])

        for key in child_keys:
            _write_branch_node(state, f"{target_symbol}:{key}", value[key])
        return

    if isinstance(value, list):
        if not value:
            out = write_value(
                state,
                target_symbol,
                [],
                writer="editor",
                op="editor_save",
            )
            if out.get("error"):
                raise ValueError(out["error"])
            return
        for index, item in enumerate(value):
            _write_branch_node(state, f"{target_symbol}:{index}", item)
        return

    out = write_value(state, target_symbol, value, writer="editor", op="editor_save")
    if out.get("error"):
        raise ValueError(out["error"])


def save_editor_target(ctx, handle: str) -> bool:
    from .. import registry as layout_registry

    if not layout_registry.has_instance(ctx, handle):
        return False

    instance = layout_registry.get_instance(ctx, handle)
    config = getattr(instance, "config", {}) or {}
    target_symbol = str(
        config.get("target_symbol")
        or layout_state.get_meta(ctx, handle, "target_symbol", "")
        or ""
    ).strip()
    target_save_mode = str(
        config.get("target_save_mode")
        or layout_state.get_meta(ctx, handle, "target_save_mode", "value")
        or "value"
    ).strip().lower()
    target_value_kind = str(
        config.get("target_value_kind")
        or layout_state.get_meta(ctx, handle, "target_value_kind", "str")
        or "str"
    ).strip()

    if not target_symbol:
        return True

    raw_text = _read_text_content(ctx, handle)
    state = ctx.get("state")
    if state is None:
        return False

    try:
        if target_symbol.startswith("#") and target_save_mode == "branch_json":
            parsed = _load_editor_value(raw_text)
            _clear_symbol_subtree(state, target_symbol)
            _write_branch_node(state, target_symbol, parsed)
        elif target_symbol.startswith("#"):
            parsed = _parse_by_value_kind(raw_text, target_value_kind)
            out = write_value(
                state,
                target_symbol,
                parsed,
                writer="editor",
                op="editor_save",
            )
            if out.get("error"):
                raise ValueError(out["error"])
        else:
            out = write_value(
                state,
                target_symbol,
                raw_text,
                writer="editor",
                op="editor_save",
            )
            if out.get("error"):
                raise ValueError(out["error"])

        layout_state.set_meta(ctx, handle, "last_save_error", "")
        layout_state.set_meta(ctx, handle, "last_saved_at", layout_state.timestamp_utc())
        return True
    except Exception as exc:
        error_text = str(exc)
        previous = str(layout_state.get_meta(ctx, handle, "last_save_error", "") or "")
        layout_state.set_meta(ctx, handle, "last_save_error", error_text)
        if error_text != previous:
            layout_state.log_error(ctx, f"editor.save:{handle}", error_text, error="editor_save")
        return False


class EditorInstance(LayoutInstance):
    MODULE = MODULE
    TITLE = TITLE
    STORAGE_PREFIX = STORAGE_PREFIX
    PRIMARY_WRITE_FIELD = PRIMARY_WRITE_FIELD

    def get_title(self) -> str:
        explicit = str(self.config.get("title") or "").strip()
        target = str(self.config.get("target_symbol") or "").strip()
        suffix = self.instance_suffix

        if explicit:
            return explicit
        if target and suffix:
            return f"EDITOR[{suffix}] {target}"
        if target:
            return f"EDITOR {target}"
        return "EDITOR" if not suffix else f"EDITOR[{suffix}]"

    def get_prompt(self) -> str:
        explicit = str(self.config.get("prompt") or "").strip()
        target = str(self.config.get("target_symbol") or "").strip()
        suffix = self.instance_suffix

        if explicit:
            return explicit
        if target:
            return f"edit[{target}]> "
        return "editor> " if not suffix else f"editor.{suffix}> "

    def get_render(self) -> str:
        return "\n".join(layout_state.normalize_lines(layout_state.get_primary(self.ctx, self.handle)))

    def save(self) -> bool:
        return save_editor_target(self.ctx, self.handle)

    def handle_input(self, line: str) -> dict[str, Any]:
        layout_state.append_primary(self.ctx, self.handle, str(line or ""))
        self.save()
        return dispatch_self()

    def handle_key(self, key: str) -> dict[str, Any]:
        if str(key).lower() != "ctrl+l":
            return dispatch_none()
        layout_state.clear_primary(self.ctx, self.handle)
        self.save()
        return dispatch_self()



def create_instance(ctx, handle: str, config: dict[str, Any] | None = None):
    return EditorInstance(ctx, handle, config)



def clone_instance(ctx, src_instance, new_handle: str):
    payload = src_instance.serialize() if hasattr(src_instance, "serialize") else {"config": dict(getattr(src_instance, "config", {}))}
    instance = EditorInstance(ctx, new_handle, dict(getattr(src_instance, "config", {})))
    instance.restore(payload)
    return instance

