# system/layout/modules/q.py

from __future__ import annotations

import json
import threading
import time
from ast import literal_eval
from typing import Any

from .. import state as layout_state
from ..contracts import LayoutInstance, dispatch_cs, dispatch_none, dispatch_self
from ..ui_control import request_redraw

try:
    from system.cs.lib import qcall as _qcall

    QCallError = getattr(_qcall, "QCallError", RuntimeError)
    get_live_chat = getattr(_qcall, "get_live_chat", None)
    get_live_packet = getattr(_qcall, "get_live_packet", None)
    get_live_thinking = getattr(_qcall, "get_live_thinking", None)
    q_chat = getattr(_qcall, "q_chat", None)
    response_symbol_for_profile = getattr(_qcall, "response_symbol_for_profile", None)
    thinking_symbol_for_profile = getattr(_qcall, "thinking_symbol_for_profile", None)
    role_symbol_for_profile = getattr(_qcall, "role_symbol_for_profile", None)
    set_active_profile = getattr(_qcall, "set_active_profile", None)
    system_prompt_symbol_for_profile = getattr(_qcall, "system_prompt_symbol_for_profile", None)

except Exception:  # pragma: no cover
    QCallError = RuntimeError
    get_live_chat = None
    get_live_packet = None
    get_live_thinking = None
    q_chat = None
    response_symbol_for_profile = None
    thinking_symbol_for_profile = None
    role_symbol_for_profile = None
    set_active_profile = None
    system_prompt_symbol_for_profile = None

MODULE = "q"
TITLE = "Q"
STORAGE_PREFIX = "Q"
PRIMARY_WRITE_FIELD = "ch"

DEFAULT_CONFIG = {
    "title": "Q",
    "prompt": "q> ",
    "profile": "default",
}

CONFIG_SCHEMA = {
    "title": "string?",
    "prompt": "string?",
    "instance_suffix": "string?",
    "profile": "string?",
}

KEYBINDS = {}


class QInstance(LayoutInstance):
    MODULE = MODULE
    TITLE = TITLE
    STORAGE_PREFIX = STORAGE_PREFIX
    PRIMARY_WRITE_FIELD = PRIMARY_WRITE_FIELD

    def __init__(self, ctx, handle: str, config: dict[str, Any] | None = None):
        super().__init__(ctx, handle, config)
        self._lock = threading.RLock()
        self._busy = False
        self._notice = ""
        self._last_live_redraw = 0.0
        self._live_redraw_interval = 0.5

    @property
    def profile(self) -> str:
        value = str(self.config.get("profile") or "").strip()
        if value:
            return value
        suffix = self.instance_suffix
        return suffix or "default"

    def get_title(self) -> str:
        explicit = str(self.config.get("title") or "").strip()
        if explicit:
            return explicit
        profile = self.profile
        return "Q" if profile == "default" else f"Q[{profile}]"

    def get_prompt(self) -> str:
        explicit = str(self.config.get("prompt") or "").strip()
        if explicit:
            return explicit
        profile = self.profile
        return "q> " if profile == "default" else f"q.{profile}> "

    def _touch_live(self, *, force: bool = False) -> None:
        now = time.monotonic()
        if not force and (now - self._last_live_redraw) < self._live_redraw_interval:
            return

        self._last_live_redraw = now
        self.refresh_render_snapshot(redraw_if_active=False)

        if self.is_active():
            request_redraw(self.ctx, force=True)

    def _read_role_prompt(self, role_name: str) -> str:
        role_name = str(role_name or "").strip()
        if not role_name:
            return ""

        candidates = [
            f"#SYSTEM:config:q:roles:{role_name}",
            f"#SYSTEM:config:q:role:{role_name}",
            f"$SYSTEM:q:roles:{role_name}",
            f"$SYSTEM:q:role:{role_name}",
        ]

        for symbol in candidates:
            out = self.ctx["state"].get(symbol)
            if not out.get("error") and out.get("result") is not None:
                return str(out.get("result") or "")

        return role_name

    def _apply_role_system_prompt(self) -> None:
        if not callable(role_symbol_for_profile) or not callable(system_prompt_symbol_for_profile):
            return

        profile = self.profile
        role_symbol = role_symbol_for_profile(profile)
        role_value = ""

        out = self.ctx["state"].get(role_symbol)
        if not out.get("error") and out.get("result") is not None:
            role_value = str(out.get("result") or "").strip()

        if not role_value:
            config_q = self.ctx.get("config", {}).get("q", {})
            profile_cfg = config_q.get(profile, {}) if isinstance(config_q, dict) else {}
            for key in ("role", "system_role", "role_name"):
                value = profile_cfg.get(key) if isinstance(profile_cfg, dict) else None
                if isinstance(value, str) and value.strip():
                    role_value = value.strip()
                    break

        if not role_value:
            state_candidates = [
                f"#SYSTEM:config:q:{profile}:role",
                f"#SYSTEM:config:q:default:role",
                f"$SYSTEM:q:{profile}:role",
                f"$SYSTEM:q:default:role",
                f"$Q.{profile}:role",
                "$Q:role" if profile == "default" else "",
            ]
            for symbol in state_candidates:
                if not symbol:
                    continue
                out = self.ctx["state"].get(symbol)
                if not out.get("error") and out.get("result") is not None:
                    value = str(out.get("result") or "").strip()
                    if value:
                        role_value = value
                        break

        if not role_value:
            return

        system_prompt = self._read_role_prompt(role_value)
        target = system_prompt_symbol_for_profile(profile)
        layout_state.set_value(self.ctx, target, system_prompt)

    def _coerce_record(self, value: Any) -> Any:
        if isinstance(value, dict):
            return value
        if isinstance(value, str):
            text = value.strip()
            if text.startswith("{") and text.endswith("}"):
                for loader in (json.loads, literal_eval):
                    try:
                        parsed = loader(text)
                        if isinstance(parsed, dict):
                            return parsed
                    except Exception:
                        pass
        return value

    def _format_record(self, idx: int, value: Any) -> list[str]:
        item = self._coerce_record(value)
        tag = f"{int(idx):05d}"

        if isinstance(item, dict):
            prompt = str(item.get("prompt") or "")
            response = str(item.get("response") or "")
            if prompt or response or ("done" in item):
                return [f"[{tag}] q> {prompt}", f"[{tag}] a> {response}"]
            return [str(item)]

        if isinstance(item, str):
            return [item]

        return [str(item)]

    def _current_history_source(self) -> Any:
        target = self.primary_target
        parser = self.ctx["parser"]

        if callable(get_live_chat):
            live = get_live_chat(parser, target)
            if isinstance(live, dict):
                return live

        return layout_state.get_primary(self.ctx, self.handle)

    def _current_response_text(self) -> str:
        parser = self.ctx["parser"]
        symbol = response_symbol_for_profile(self.profile) if callable(response_symbol_for_profile) else "$Q:response"

        live = self._current_live_packet()
        live_symbol = str(live.get("response_symbol") or "")
        if symbol and live_symbol == symbol:
            return str(live.get("response") or "")

        value = layout_state.get_value(self.ctx, symbol, "")
        return str(value or "")

    def _current_thinking_text(self) -> str:
        parser = self.ctx["parser"]
        symbol = thinking_symbol_for_profile(self.profile) if callable(thinking_symbol_for_profile) else "$Q:thinking"

        if callable(get_live_thinking):
            try:
                return str(get_live_thinking(parser, symbol) or "")
            except Exception:
                pass

        value = layout_state.get_value(self.ctx, symbol, "")
        return str(value or "")

    def _current_live_packet(self) -> dict[str, Any]:
        if not callable(get_live_packet):
            return {}

        try:
            packet = get_live_packet(self.ctx["parser"])
        except Exception:
            return {}

        if not isinstance(packet, dict):
            return {}

        if str(packet.get("profile") or "default") != self.profile:
            return {}

        return packet

    def _render_history(self) -> list[str]:
        current = self._current_history_source()
        out: list[str] = []

        if isinstance(current, dict):
            numeric_rows: list[tuple[int, Any]] = []
            other_rows: list[tuple[str, Any]] = []

            for key, value in current.items():
                try:
                    numeric_rows.append((int(str(key)), value))
                except Exception:
                    other_rows.append((str(key), value))

            numeric_rows.sort(key=lambda x: x[0])
            other_rows.sort(key=lambda x: x[0])

            for idx, value in numeric_rows:
                out.extend(self._format_record(idx, value))

            base_idx = len(numeric_rows)
            for offset, (_, value) in enumerate(other_rows):
                out.extend(self._format_record(base_idx + offset, value))

            return out

        if isinstance(current, list):
            for idx, value in enumerate(current):
                out.extend(self._format_record(idx, value))
            return out

        if isinstance(current, str):
            lines = current.splitlines() or ([current] if current else [])
            for idx, value in enumerate(lines):
                out.extend(self._format_record(idx, value))
            return out

        if current is not None:
            out.extend(self._format_record(0, current))

        return out

    def get_render(self) -> str:
        out: list[str] = []

        if self._notice:
            out.append(self._notice)

        live = self._current_live_packet()
        live_done_raw = live.get("done")
        live_done = 1 if live_done_raw is None else int(live_done_raw)

        response_text = self._current_response_text()
        thinking_text = self._current_thinking_text()

        if live_done == 0:
            has_live = False

            if thinking_text:
                has_live = True
                out.append("[thinking]")
                out.append("-" * 10)
                out.extend(thinking_text.splitlines() or [thinking_text])

            if response_text:
                has_live = True
                if out:
                    out.append("")
                out.append("[response]")
                out.append("-" * 10)
                out.extend(response_text.splitlines() or [response_text])

            if has_live:
                return "\n".join(out)

        out.extend(self._render_history())
        return "\n".join(out)

    def _clear_q_state(self) -> None:
        base = self.storage_root
        layout_state.set_value(self.ctx, f"{base}:ch", {})
        layout_state.set_value(self.ctx, f"{base}:response", "")
        layout_state.set_value(self.ctx, f"{base}:thinking", "")
        self._notice = ""
        layout_state.set_status(self.ctx, self.handle, "ok")
        self._touch_live(force=True)

    def _run_q_request(self, prompt_text: str) -> None:
        parser = self.ctx["parser"]
        profile = self.profile
        final_text = ""

        try:
            layout_state.set_status(self.ctx, self.handle, "run")
            self._touch_live(force=True)

            if callable(set_active_profile):
                set_active_profile(parser, profile)

            self._apply_role_system_prompt()
            command_token = "q" if profile == "default" else f"q.{profile}"

            def _on_chunk(_chunk: str, full_text: str, _chat_symbol: str, _key: str) -> None:
                nonlocal final_text
                final_text = str(full_text or "")
                self._touch_live(force=False)

            def _on_done(full_text: str, _chat_symbol: str, _key: str) -> None:
                nonlocal final_text
                final_text = str(full_text or "")
                self._touch_live(force=True)

            if not callable(q_chat):
                raise RuntimeError("qcall unavailable")

            out = q_chat(
                parser,
                command_token,
                prompt_text,
                on_chunk=_on_chunk,
                on_done=_on_done,
            )

            returned_text = str((out or {}).get("message") or "")
            if len(returned_text) > len(final_text):
                final_text = returned_text

            self._notice = ""
            layout_state.set_status(self.ctx, self.handle, "ok")

        except QCallError as exc:  # type: ignore[misc]
            self._notice = f"[error] {exc}"
            layout_state.set_status(self.ctx, self.handle, "error")
            layout_state.log_error(self.ctx, self.handle, str(exc), error="ERR_RUNTIME")

        except Exception as exc:
            self._notice = f"[error] {exc}"
            layout_state.set_status(self.ctx, self.handle, "error")
            layout_state.log_error(self.ctx, self.handle, str(exc), error="ERR_RUNTIME")

        finally:
            with self._lock:
                self._busy = False
            self._touch_live(force=True)

    def handle_input(self, line: str) -> dict[str, Any]:
        clean = str(line or "").strip()
        if not clean:
            return dispatch_none()

        if clean == "/clear":
            self._clear_q_state()
            return dispatch_self()

        if clean.lower().startswith("cs "):
            return dispatch_cs(clean[3:].strip())

        with self._lock:
            if self._busy:
                self._notice = "[busy] q request already in flight"
                self._touch_live(force=True)
                return dispatch_self()
            self._busy = True

        self._notice = ""

        thread = threading.Thread(
            target=self._run_q_request,
            args=(clean,),
            daemon=True,
            name=f"aigmos-layout-q-{self.handle}",
        )
        thread.start()
        return dispatch_self()

    def serialize(self) -> dict[str, Any]:
        payload = super().serialize()
        payload["notice"] = self._notice
        return payload

    def restore(self, payload: dict[str, Any] | None) -> None:
        super().restore(payload)
        if not isinstance(payload, dict):
            return
        self._notice = str(payload.get("notice") or "")
        self.touch(redraw_if_active=False)


def create_instance(ctx, handle: str, config: dict[str, Any] | None = None):
    return QInstance(ctx, handle, config)

